    ];
    const $=id=>document.getElementById(id), money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(n)||0);
    const formatProposalDate=()=>new Intl.DateTimeFormat('pt-BR',{dateStyle:'long',timeZone:'America/Bahia'}).format(new Date());
    const defaultIntro='Esta proposta reúne os serviços, entregas e condições alinhados para o seu projeto.';
    const makeProposalNumber=()=>`S3-${new Date().toISOString().slice(0,10).replaceAll('-','')}-${Math.random().toString(36).slice(2,6).toUpperCase()}`;
    const eventFields=['eventType','eventDate','venue','coverageHours','crew','photoCount','photos','videos','album','extraHour','eventDelivery'];
    const itemFields=['preset','title','description','deliverables','price','billing','discountType','discountValue','hours','costs','deadline','payment','notes','event',...eventFields];
    let catalogOverrides={};try{const v=JSON.parse(localStorage.getItem('s3-catalogo-v1')||'{}');if(v&&typeof v==='object'&&!Array.isArray(v))catalogOverrides=v}catch(_){}
    const getPreset=id=>{const p=presets.find(x=>x.id===id)||presets[0],override=catalogOverrides[p.id]||{};const result={...p,...override,id:p.id};if(override.photos!==undefined&&override.photoCount===undefined){const n=String(override.photos).match(/\d+/);result.photoCount=n?n[0]:''}return result};
    const clonePreset=(id)=>{const p=getPreset(id);return {...p,discountType:'percent',discountValue:0,uid:crypto.randomUUID?.()||String(Date.now()+Math.random()),eventDate:'',venue:'',event:!!p.event}};
