      try{const catalog=presets.map(p=>getPreset(p.id));const response=await fetch('/api/ai/generate',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({brief,catalog})});const data=await response.json();if(!response.ok)throw Error(data.error||'Não foi possível gerar a proposta.');aiDraft=data;
        const summary=$('aiSummary');summary.replaceChildren(el('p',{text:(data.client?'Cliente: '+data.client+' · ':'')+(data.location?'Local: '+data.location+' · ':'')+(data.intro||'')}));
        const cards=$('aiCards');cards.replaceChildren();for(const item of data.services){const card=el('div',{class:'aiCard'});card.append(el('h3',{text:item.title}),el('p',{text:item.description}),el('p',{text:`${money(item.price)}${item.billing==='mensal'?' / mês':''} · ${item.deadline||'Prazo a combinar'}`}),el('p',{text:'Pagamento: '+(item.payment||'A combinar')}));if(item.deliverables)card.append(el('p',{text:'Entregas: '+item.deliverables.split('\n').join(' · ')}));if(item.defaults.includes('price')||item.defaults.includes('deadline')||item.defaults.includes('payment'))card.append(el('p',{class:'hint',text:'Preço, prazo ou pagamento ausente no resumo: aplicado o padrão do catálogo.'}));cards.append(card)}
        const warnings=$('aiWarnings');warnings.replaceChildren(...(data.warnings||[]).map(w=>el('p',{text:w})));$('aiResult').hidden=false;$('aiStatus').textContent='Rascunho gerado. Confira cada serviço antes de usar.';
      }catch(error){$('aiStatus').textContent=error.message||'Não foi possível gerar a proposta.'}finally{$('aiGenerate').disabled=false;$('aiGenerate').textContent='Gerar rascunho com IA'}
    });
    function applyAi(replace){if(!aiDraft)return;const items=aiDraft.services.map(item=>({...clonePreset(item.preset),...item,uid:clonePreset(item.preset).uid}));if(replace){state.items=items;state.proposalNumber=makeProposalNumber()}else state.items.push(...items);if(replace)state.location=aiDraft.location||'';else if(aiDraft.location&&!state.location)state.location=aiDraft.location;if(aiDraft.client&&(replace||!state.client))state.client=aiDraft.client;if(aiDraft.intro&&(replace||state.introAuto)){state.intro=aiDraft.intro;state.introAuto=false}for(const id of ['client','location','intro'])$(id).value=state[id]||'';render();saveHistory(true);showTab('proposal');$('status').textContent='Proposta da IA adicionada ao histórico. Revise e salve novamente se fizer alterações.'}
    $('aiReplace').addEventListener('click',()=>applyAi(true));$('aiAppend').addEventListener('click',()=>applyAi(false));
    for(const id of ['client','contact','location','intro','validity','generalNotes'])$(id).addEventListener('input',e=>{state[id]=e.target.value;if(id==='intro')state.introAuto=false;renderPreview()});
    $('services').addEventListener('input',e=>{const node=e.target,uid=node.dataset.uid,key=node.dataset.field;if(!uid||!key||key==='preset')return;const item=state.items.find(x=>x.uid===uid);if(!item)return;item[key]=key==='event'?node.checked:node.value;if(key==='title'||key==='billing'){const card=node.closest('.service');card.querySelector('.serviceHead h3').textContent=`${state.items.indexOf(item)+1}. ${item.title||'Novo serviço'}`;card.querySelector('.serviceHead small').textContent=item.billing==='mensal'?'Cobrança recorrente mensal':'Projeto ou evento único'}if(key==='event')node.closest('.service').querySelector('.eventBox').hidden=!item.event;if(['hours','costs','price','discountValue','discountType'].includes(key))updateEconomics(item);renderPreview()});
    $('services').addEventListener('change',e=>{const node=e.target,uid=node.dataset.uid;if(!uid)return;const item=state.items.find(x=>x.uid===uid);if(!item)return;if(node.dataset.field==='preset'){const previous={uid:item.uid};const fresh=clonePreset(node.value);Object.assign(item,fresh,previous);render()}else if(node.dataset.field==='event'){item.event=node.checked;node.closest('.service').querySelector('.eventBox').hidden=!item.event;renderPreview()}});
    $('services').addEventListener('click',e=>{const b=e.target.closest('button[data-action]');if(!b)return;const index=state.items.findIndex(x=>x.uid===b.dataset.uid);if(index<0)return;
      if(b.dataset.action==='remove'){state.items.splice(index,1);render()}
      if(b.dataset.action==='duplicate'){state.items.splice(index+1,0,{...state.items[index],uid:clonePreset('livre').uid});render()}
      if(b.dataset.action==='refresh'){const prior=state.items[index],newItem=clonePreset(prior.preset);state.items[index]={...newItem,uid:prior.uid,eventDate:prior.eventDate||'',venue:prior.venue||''};render();$('status').textContent='Padrão atualizado neste item. Revise preço e condições antes de enviar.'}
      if(b.dataset.action==='payment'){state.items[index].payment=b.dataset.value;render()}
    });
    $('add').addEventListener('click',()=>{state.items.push(clonePreset($('newPreset').value));render();$('services').lastElementChild?.scrollIntoView({block:'center',behavior:'smooth'})});
    $('saveHistory').addEventListener('click',()=>saveHistory());
    $('print').addEventListener('click',()=>{if(!state.items.length){$('status').textContent='Inclua ao menos um serviço antes de salvar a proposta.';return}if(state.items.some(x=>!Number(x.price))){$('status').textContent='Defina o preço de todos os serviços antes de salvar a proposta.';return}renderPreview();window.print()});
    $('copy').addEventListener('click',async()=>{const lines=[`Olá, ${state.contact.trim()||state.client.trim()||'tudo bem'}! Preparei uma proposta da S3 Mídia para ${state.client.trim()||'você'}.`,'',...state.items.map(x=>{const off=lineDiscount(x),final=Math.max(0,Number(x.price)||0)-off;return`${x.title}: ${money(final)}${x.billing==='mensal'?' por mês':''}${off?` (desconto de ${money(off)}${x.billing==='mensal'?' ao mês':''})`:''}\n${x.deliverables.split('\n').filter(Boolean).map(y=>'• '+y.trim()).join('\n')}\nPagamento: ${x.payment}`}),'',`Validade: ${state.validity||7} dias. Posso explicar os próximos passos?`];try{await navigator.clipboard.writeText(lines.join('\n'));$('status').textContent='Resumo copiado. Revise antes de enviar.'}catch(_){$('status').textContent='Não foi possível copiar neste navegador; use o PDF.'}});
    $('clear').addEventListener('click',()=>{try{localStorage.removeItem('s3-proposta-rascunho-v2');localStorage.removeItem('s3-proposta-rascunho-v1')}catch(_){}state={proposalNumber:makeProposalNumber(),client:'',contact:'',location:'',intro:defaultIntro,introAuto:true,validity:'7',generalNotes:'',items:[clonePreset('presenca')]};for(const id of ['client','contact','location','intro','validity','generalNotes'])$(id).value=state[id]||'';render();$('status').textContent='Rascunho limpo.'});
    let saved;try{saved=JSON.parse(localStorage.getItem('s3-proposta-rascunho-v2')||'null');if(saved&&Array.isArray(saved.items)){saved.items=saved.items.filter(x=>x&&typeof x.uid==='string').map(x=>{const item={...clonePreset(x.preset||'livre'),...x};if(x.photoCount===undefined&&x.photos){const n=String(x.photos).match(/\d+/);item.photoCount=n?n[0]:''}return item});state={...state,...saved};if(saved.introAuto===undefined)state.introAuto=saved.intro===defaultIntro}else{const old=JSON.parse(localStorage.getItem('s3-proposta-rascunho-v1')||'null');if(old&&old.preset){const item=clonePreset(old.preset);for(const key of itemFields)if(old[key]!==undefined)item[key]=old[key];state={client:old.client||'',contact:old.contact||'',location:'',intro:old.goal||defaultIntro,introAuto:!old.goal,validity:old.validity||'7',generalNotes:'',items:[item]}}}}catch(_){}
    for(const id of ['client','contact','location','intro','validity','generalNotes'])$(id).value=state[id]||'';render();
    if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'preparar_proposta_s3',title:'Preparar proposta S3',description:'Preenche o rascunho local com cliente e uma lista de serviços; não envia ao cliente.',inputSchema:{type:'object',properties:{cliente:{type:'string'},servicos:{type:'array',minItems:1,items:{type:'string',enum:presets.map(p=>p.id)}}},required:['cliente','servicos'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.cliente!=='string'||!input.cliente.trim()||!Array.isArray(input.servicos)||!input.servicos.length||input.servicos.some(id=>!presets.some(p=>p.id===id)))throw Error('Informe cliente e serviços válidos.');state.client=input.cliente.trim();state.items=input.servicos.map(clonePreset);$('client').value=state.client;render();return{cliente:state.client,servicos:state.items.map(x=>x.title),estado:'rascunho local atualizado'}}})).catch(()=>{})}catch(_){}}
  </script>
</body>
</html>

